<script setup lang="ts">
import { ref } from 'vue';import { startInterview,answerInterview,getInterviewReport } from '@/api/interview'
const jobId=ref('');const resumeText=ref('');const interviewId=ref<number|null>(null);const question=ref('');const answer=ref('');const feedback=ref<{score:number;strengths:string[];improvements:string[]}|null>(null);const report=ref<any>(null);const error=ref('')
async function start(){try{const r=(await startInterview({sourceType:'EXTERNAL_RESUME',externalResumeText:resumeText.value,jobDescriptionId:Number(jobId.value),interviewMode:'TECHNICAL'})).data.data;interviewId.value=r.interviewId;question.value=r.firstQuestion}catch{error.value='无法开始面试，请确认 AI 授权、JD 和简历文本。'}}
async function submit(){if(!interviewId.value)return;try{const r=(await answerInterview(interviewId.value,answer.value)).data.data;feedback.value={score:r.roundScore,...r.feedback};answer.value='';question.value=r.nextQuestion??'面试已完成，可查看报告。'}catch{error.value='回答提交失败。'}}
async function loadReport(){if(interviewId.value)report.value=(await getInterviewReport(interviewId.value)).data.data}
</script>
<template><section class="workspace-page"><p class="eyebrow">AI interview</p><h1>AI 模拟面试</h1><p>AI 只基于你提交的简历文本和 JD 提问；回答与建议分开保存。</p><p v-if="error" class="form-error">{{error}}</p><form v-if="!interviewId" class="workspace-card" @submit.prevent="start"><label>JD ID<input v-model="jobId" inputmode="numeric" /></label><label>简历文本<textarea v-model="resumeText" rows="10" /></label><button class="btn-neon btn-primary">开始技术面试</button></form><div v-else class="workspace-card"><h2>{{question}}</h2><form @submit.prevent="submit"><label>你的回答<textarea v-model="answer" rows="6" /></label><button class="btn-neon btn-primary">提交回答</button></form><div v-if="feedback"><strong>本轮 {{feedback.score}} 分</strong><ul><li v-for="x in feedback.strengths" :key="x">{{x}}</li><li v-for="x in feedback.improvements" :key="x">{{x}}</li></ul></div><button class="btn-neon btn-ghost" @click="loadReport">查看报告</button><article v-if="report"><h2>总分 {{report.totalScore}}</h2><p>{{report.summary}}</p><h3>简历建议</h3><ul><li v-for="x in report.resumeSuggestions" :key="x">{{x}}</li></ul></article></div></section></template>
